{"mode":0,"unit":"","interval":900000,"update":{"init":"this.status = nvg.Value.Null;
local.url = "https://wttr.in/?A&format=%l+%m\n%c%C+%t+%h ";
// Reference
// https://github.com/chubin/wttr.in","execute":"if (this.status === nvg.Value.Loading)
 return;

this.status = nvg.Value.Loading;

const value = this;
const xhr = new XMLHttpRequest();
xhr.onerror = function () {
 value.status = nvg.Value.Error;
}
xhr.onload = function () {
 if (xhr.status >= 200 && xhr.status < 300) {
 value.current = xhr.response;
 value.status = nvg.Value.Ready;
 } else { xhr.onerror(); }
}
xhr.responseType = 'text';
xhr.open("GET", local.url);
xhr.send();","values":[],"actions":[]},"label":"#Version: October 2, 2026","source":"nvg://system/data#misc","value":"script-value"}
